class Cuenta:
    def __init__(self, saldo):
        self._saldo = saldo

    @property
    def saldo(self):
        return self._saldo

    @saldo.setter
    def saldo(self, valor):
        if valor < 0:
            raise ValueError("saldo no puede ser negativo")
        self._saldo = valor

c = Cuenta(100)
print(c.saldo)
c.saldo = 150
print(c.saldo)
try:
    c.saldo = -10
except ValueError as e:
    print("Error:", e)
